function checkPasswordStrength(e){const t=[];return/.{6,}/.test(e)||t.push("Setidaknya 6 karakter"),t}document.getElementById("password").addEventListener("input",e=>{const t=checkPasswordStrength(e.target.value),n=document.getElementById("passwordFeedback");t.length?(n.innerText=t.join(", "),n.setAttribute("style","display:block;")):n.innerText=""}),document.getElementById("auth_confirm_password").addEventListener("input",e=>{const t=document.getElementById("password").value,n=document.getElementById("confirmPasswordFeedback");e.target.value.length>5&&e.target.value!==t?(n.innerText="Konfirmasi password tidak sesuai",n.setAttribute("style","display:block;")):n.innerText=""});